export function revisedPatterns(pattern) {
  return artworkVersions.flatMap((artwork,index) => {
    const shapes = artwork[pattern.id];
    if (!shapes) return [];
    const version = index ? `-v${index+1}` : '';
    return [{...pattern, id: `${pattern.id}${version}-clean`, shapes}];
  });
}
